const response = $json;

const text = response.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
  throw new Error("Gemini returned no text.");
}

let ai;

try {
  ai = JSON.parse(text);
} catch (e) {
  throw new Error(`Invalid Gemini JSON:\n${text}`);
}

const original = $("IF Merchant Known").item.json;

return {
  json: {
    ...original,

    display_name:
      ai.display_name ||
      original.display_name ||
      original.merchant,

    normalized_merchant:
      original.normalized_merchant,

    category:
      ai.category ||
      original.category ||
      "Other",

    confidence:
      Number(ai.confidence ?? 50),

    category_source: "ai"
  }
};

const j = $json;

// Get input raw merchant or description
const raw = String(
  j.merchant ??
  j.merchant_raw ??
  j.description ??
  ""
).trim();

// --------------------------------------------------
// 1. Canonical Merchant Aliases
// --------------------------------------------------
const aliases = [
  [/AMAZON/i, "AMAZON"],
  [/DECATHLON/i, "DECATHLON"],
  [/BIGBASKET/i, "BIGBASKET"],
  [/MYNTRA/i, "MYNTRA"],
  [/ZERODHA/i, "ZERODHA"],
  [/HPCL/i, "HPCL"],
  [/INDIAN\s*OIL|IOCL/i, "IOCL"],
  [/BHARAT\s*PETROLEUM|BPCL/i, "BPCL"],
  [/ULTA/i, "ULTA"],
  [/GAP/i, "GAP"],
  [/MACY/i, "MACYS"],
  [/LYFT/i, "LYFT"],
  [/BATH\s*&\s*BODY|BATH\s*AND\s*BODY/i, "BATHBODYWORKS"],
  [/H&M|H\s*&\s*M/i, "HM"],
  [/DAISO/i, "DAISO"],
  [/COACH/i, "COACH"],
  [/NJTRANSIT|NJ\s*TRANSIT/i, "NJTRANSIT"],
  [/ALASKA\s*AIR|ALASKA\s*A/i, "ALASKAAIR"],
  [/LADERACH/i, "LADERACH"],
  [/SOCIAL/i, "SOCIAL"],
  [/SWIGGY/i, "SWIGGY"],
  [/ZOMATO/i, "ZOMATO"],
  [/STARBUCKS/i, "STARBUCKS"],
  [/DOMINO/i, "DOMINOS"],
  [/UBER/i, "UBER"],
];

// --------------------------------------------------
// 2. Basic cleaning for normalized_merchant
// --------------------------------------------------
function getNormalizedMerchant(value) {
  if (!value) return "UNKNOWN";

  const upper = value.toUpperCase();

  // First check aliases
  for (const [regex, canonical] of aliases) {
    if (regex.test(upper)) {
      return canonical;
    }
  }

  let m = upper;

  // Remove company suffixes
  m = m
    .replace(/\bPRIVATE\s+LIMITED\b/g, " ")
    .replace(/\bPVT\.?\s*LTD\.?\b/g, " ")
    .replace(/\bLIMITED\b/g, " ")
    .replace(/\bLTD\.?\b/g, " ")
    .replace(/\bLLP\b/g, " ")
    .replace(/\bINDIA\b/g, " ");

  // Remove payment noise
  m = m
    .replace(/\bUPI\b/g, " ")
    .replace(/\bPOS\b/g, " ")
    .replace(/\bECOM\b/g, " ")
    .replace(/\bONLINE\b/g, " ")
    .replace(/\bPAYMENT\b/g, " ");

  // Remove store IDs / terminal IDs
  m = m
    .replace(/#\d+/g, " ")
    .replace(/\b\d{3,}\b/g, " ");

  // Remove punctuation
  m = m.replace(/[^A-Z0-9 ]/g, " ");

  // Collapse spaces
  m = m.replace(/\s+/g, " ").trim();

  // Stable lookup key
  m = m.replace(/\s/g, "");

  return m || "UNKNOWN";
}

// --------------------------------------------------
// 3. Extract clean canonical display_name
// --------------------------------------------------
function getDisplayName(rawText, normalizedText) {

  if (!rawText || normalizedText === "UNKNOWN") {
    return "Unknown Merchant";
  }

  const upper = rawText.toUpperCase();

  const displayAliases = [
    [/AMAZON/i, "Amazon"],
    [/DECATHLON/i, "Decathlon"],
    [/BIGBASKET/i, "BigBasket"],
    [/MYNTRA/i, "Myntra"],
    [/ZERODHA/i, "Zerodha"],
    [/HPCL/i, "HPCL"],
    [/INDIAN\s*OIL|IOCL/i, "Indian Oil"],
    [/BHARAT\s*PETROLEUM|BPCL/i, "Bharat Petroleum"],
    [/ULTA/i, "Ulta Beauty"],
    [/GAP/i, "Gap"],
    [/MACY/i, "Macy's"],
    [/LYFT/i, "Lyft"],
    [/BATH\s*&\s*BODY|BATH\s*AND\s*BODY/i, "Bath & Body Works"],
    [/H&M|H\s*&\s*M/i, "H&M"],
    [/DAISO/i, "Daiso"],
    [/COACH/i, "Coach"],
    [/NJTRANSIT|NJ\s*TRANSIT/i, "NJ Transit Rail"],
    [/ALASKA\s*AIR|ALASKA\s*A/i, "Alaska Airlines"],
    [/LADERACH/i, "Läderach"],
    [/SOCIAL/i, "Social"],
    [/SWIGGY/i, "Swiggy"],
    [/ZOMATO/i, "Zomato"],
    [/STARBUCKS/i, "Starbucks"],
    [/DOMINO/i, "Domino's"],
    [/UBER/i, "Uber"],
  ];

  for (const [regex, display] of displayAliases) {
    if (regex.test(upper)) {
      return display;
    }
  }

  return normalizedText
    .replace(/([A-Z])/g, " $1")
    .trim()
    .replace(/\b\w/g, c => c.toUpperCase());
}

const normalized = getNormalizedMerchant(raw);
const displayName = getDisplayName(raw, normalized);

// Return structure matching your target database schema
return {
  json: {
    ...j,
    normalized_merchant: normalized,
    display_name: displayName,
    category: j.category || "Uncategorized",
    confidence: normalized === "UNKNOWN" ? 20 : 90
  }
};

return {
  json: {
    message_id: $json.message_id,
    bank_name: $json.bank_name,
    password: $json.password,
    card_last4: $json.card_last4,
    business_personal: $json.business_personal,
    subject: $json.subject,
    timestamp: $json.timestamp
  }
};

// Current transaction
const txn = $json;

// Validate required fields
if (!txn.message_id) {
  throw new Error("message_id is missing from transaction.");
}

// Find the matching statement metadata using message_id
const meta = $('Merge Statement + PDF')
  .all()
  .find(item => item.json.message_id === txn.message_id);

if (!meta) {
  throw new Error(`No statement metadata found for message_id: ${txn.message_id}`);
}

return {
  json: {
    ...txn,

    // Statement metadata
    bank_name: meta.json.bank_name ?? null,
    card_last4: meta.json.card_last4 ?? null,
    business_personal: meta.json.business_personal ?? null,
    password: meta.json.password ?? null,
    sender_email: meta.json.sender_email ?? null,
    subject: meta.json.subject ?? null,
    timestamp: meta.json.timestamp ?? null,

    // Statement metadata (optional)
    statement_id: meta.json.statement_id ?? null,
    statement_month: meta.json.statement_month ?? null,
    source_file: meta.json.source_file ?? null,

    // Processing metadata
    parser_version: "v2",
    extraction_method: "ai"
  }
};

const merchantCache = {};

for (const item of $input.all()) {

    const merchant = item.json.normalized_merchant;

    if (!merchant) continue;

    const key = merchant.trim().toUpperCase();

    merchantCache[key] = {
        normalized_merchant: merchant,
        display_name: item.json.display_name,
        category: item.json.category,
        confidence: item.json.confidence
    };

}

return [{
    json: {
        merchant_cache: merchantCache,
        merchant_count: Object.keys(merchantCache).length
    }
}];

// Current transaction
const txn = $input.item.json;

// Merchant cache built earlier
const cache = $("Build Merchant Cache").first().json.merchant_cache || {};

// Normalize lookup key
const key = (txn.normalized_merchant || "")
    .trim()
    .toUpperCase();

// Lookup merchant
const merchant = cache[key];

if (merchant) {

    return {
        json: {

            ...txn,

            merchant_found: true,

            display_name: merchant.display_name,
            category: merchant.category,
            confidence: merchant.confidence,

            category_source: "merchant_memory"

        }
    };

}

// Merchant not found
return {
    json: {

        ...txn,

        merchant_found: false,

        category_source: "ai"

    }
};

const txn = $('Normalize Merchant').item.json;

// HTTP node returns:
// {
//   body: [ { found:true ... } ],
//   headers:{},
//   statusCode:200
// }

const lookup =
    $json.body && $json.body.length
        ? $json.body[0]
        : null;

return {
  json: {

    ...txn,

    merchant_found: Boolean(lookup?.found),

    merchant_id: lookup?.merchant_id ?? null,

    category:
      lookup?.found
        ? lookup.category
        : txn.category,

    display_name:
      lookup?.found
        ? lookup.display_name
        : txn.display_name,

    confidence:
      lookup?.found
        ? lookup.confidence
        : txn.confidence,

    category_source:
      lookup?.found
        ? "merchant_memory"
        : "ai"
  }
};

